using Godot;
namespace BloxDungoen;

public static class SelfTests
{
    public static int Run()
    {
        int failures = 0, passed = 0;
        string testRoot = System.IO.Path.Combine(ProjectSettings.GlobalizePath("res://.godot"), "rule-tests", Guid.NewGuid().ToString("N"));
        GameModel New() => new(new SaveStore(System.IO.Path.Combine(testRoot, Guid.NewGuid().ToString("N"))), 123);
        RunStats Stats() => RunStats.From(new MetaProgress());
        void Assert(bool condition, string message = "assertion failed") { if (!condition) throw new Exception(message); }
        void Test(string name, Action action) { try { action(); passed++; GD.Print("PASS " + name); } catch (Exception e) { failures++; GD.PushError("FAIL " + name + ": " + e.Message); } }
        Test("free initial fortress is valid", () => { var s = Stats(); var b = Rules.FromLayout(Definitions.StartingLayout, s); Assert(Rules.Validate(b, s) == null); Assert(Rules.Capacity(b) == 6); });
        Test("overlap and out-of-grid placement are rejected", () => { var s = Stats(); List<Block> b = [Rules.Create("core", s)]; Assert(Rules.PlacementError(b, Rules.Create("gun", s), s) != null); Assert(Rules.PlacementError(b, Rules.Create("armor", s, 5), s) != null); });
        Test("large modules require research and consume four capacity", () => { var s = Stats(); List<Block> b = [Rules.Create("core", s)]; var plate = Rules.Create("plate", s, 1); Assert(Rules.PlacementError(b, plate, s) != null); s.Size = 2; Assert(Rules.PlacementError(b, plate, s) == null); b.Add(plate); Assert(Rules.Capacity(b) == 4); Assert(b.Count == 2); });
        Test("diagonal contact cannot power a turret", () => { var s = Stats(); Assert(Rules.Validate([Rules.Create("core", s), Rules.Create("gun", s, 1, 1)], s) != null); });
        Test("large footprint transmits connectivity", () => { var s = Stats(); Assert(Rules.Connected([Rules.Create("core", s), Rules.Create("plate", s, 1), Rules.Create("gun", s, 3, 1)]).Count == 3); });
        Test("quantity and capacity are separate limits", () => { var s = Stats(); s.Count = 1; List<Block> b = [Rules.Create("core", s), Rules.Create("gun", s, 1)]; Assert(Rules.PlacementError(b, Rules.Create("armor", s, 0, 1), s) != null); s.Count = 8; s.Capacity = 1; Assert(Rules.PlacementError(b, Rules.Create("armor", s, 0, 1), s) != null); });
        Test("shortest rotation crosses the +/-PI boundary", () => { float a = Rules.Turn(MathF.PI - .01f, -MathF.PI + .01f, .03f); Assert(MathF.Abs(a - (MathF.PI + .01f)) < .001f); });
        Test("mouse following is limited to 360 degrees per second", () => { var g = New(); g.Angle = 0; g.Aim = g.Position + Vector2.Right * 300; g.Update(1f / 60); Assert(MathF.Abs(g.Angle - MathF.Tau / 60) < .001f); });
        Test("mouse dead zone holds the heading", () => { var g = New(); g.Angle = 1.2f; g.Aim = g.Position; g.Update(1f / 60); Assert(g.Angle == 1.2f); });
        Test("WASD movement remains in screen coordinates", () => { var g = New(); g.Angle = 2; g.Aim = g.Position; Vector2 p = g.Position; g.Movement = new(1, -1); g.Update(1f / 60); Assert(g.Position.X > p.X && g.Position.Y < p.Y); });
        Test("fast projectiles hit outer armor before the core", () => { var s = Stats(); var armor = Rules.Create("armor", s, 1); var core = Rules.Create("core", s); float? a = Rules.SegmentBlock(new(200, 0), new(-200, 0), armor, Vector2.Zero, 0), b = Rules.SegmentBlock(new(200, 0), new(-200, 0), core, Vector2.Zero, 0); Assert(a.HasValue && b.HasValue && a < b); });
        Test("collision geometry rotates with the hull", () => { var s = Stats(); var b = Rules.Create("armor", s, 1); Assert(Rules.SegmentBlock(new(0, 100), new(0, 20), b, Vector2.Zero, MathF.PI / 2) != null); Assert(Rules.SegmentBlock(new(0, 100), new(0, 20), b, Vector2.Zero, 0) == null); });
        Test("actual bullet damage respects the first armor impact", () => { var g = New(); g.Start(); g.WaveTimer = 999; g.Blocks = [Rules.Create("core", g.Stats), Rules.Create("armor", g.Stats, 1), Rules.Create("gun", g.Stats, -1)]; g.Position = new(700, 500); g.Angle = 0; g.Aim = g.Position; g.Bullets.Add(new() { Position = new(790, 500), Velocity = new(-600, 0), Damage = 15, Life = 1, Hostile = true, Radius = 2 }); for (int i = 0; i < 10; i++) g.Update(1f / 60); Assert(g.Blocks[0].Hp == 160 && g.Blocks[1].Hp == 95); });
        Test("broken bridge drops a damaged turret without copying it", () => { var g = New(); g.Start(); var bridge = Rules.Create("armor", g.Stats, 1); var gun = Rules.Create("gun", g.Stats, 2, rarity: 1, level: 2); gun.Hp = 33; g.Blocks = [Rules.Create("core", g.Stats), bridge, gun]; g.Hit(bridge, 999); Assert(g.Blocks.Count == 1 && g.Wrecks.Count == 1 && g.Drops.Count == 1); Assert(g.Drops[0].Module!.Hp == 33 && g.Drops[0].Module!.Id == gun.Id); var drop = g.Drops[0]; g.Drops.Clear(); g.Collect(drop); g.Collect(drop); Assert(g.Inventory.Count == 1); });
        Test("one free repair per station and wreck records are consumed", () => { var g = New(); g.Start(); g.Hit(g.Blocks[1], 999); g.Room = 3; g.EnterRoom(); g.Repair(); Assert(!g.FreeRepair && g.Wrecks.Count == 0 && g.Scrap == 0); var ids = g.Blocks.Concat(g.Inventory).Select(b => b.Id).ToList(); Assert(ids.Count == ids.Distinct().Count()); g.Blocks[0].Hp = 20; g.Repair(); Assert(g.Blocks[0].Hp == 20); });
        Test("blocked repair position goes to inventory", () => { var s = Stats(); List<Block> b = [Rules.Create("core", s), Rules.Create("gun", s, 1)]; List<Block> inv = [], wreck = [Rules.Create("armor", s, 1)]; Rules.RepairAll(b, inv, wreck, s); Assert(inv.Count == 1 && wreck.Count == 0); Rules.RepairAll(b, inv, wreck, s); Assert(inv.Count == 1); });
        Test("upgrades retain damage percentage", () => { var s = Stats(); var b = Rules.Create("armor", s, 1); b.Hp /= 2; Rules.Upgrade(b, s); Assert(MathF.Abs(b.Hp / Rules.MaxHp(b, s) - .5f) < .01f); });
        Test("combat does not allow repair or upgrade", () => { var g = New(); g.Start(); g.Scrap = 100; g.Blocks[1].Hp = 1; g.Repair(); g.Improve(g.Blocks[1].Id); Assert(g.Scrap == 100 && g.Blocks[1].Hp == 1 && g.Blocks[1].Level == 1); });
        Test("left-button firing simulation destroys a target", () => { var g = New(); g.Start(); g.WaveTimer = 999; g.Spawn("shooter", new(1000, 800)); g.Enemies[0].Hp = g.Enemies[0].Max = 26; g.Enemies[0].Timer = 999; g.Aim = new(1000, 800); g.Firing = true; for (int i = 0; i < 120; i++) g.Update(1f / 60); Assert(g.Kills >= 1); });
        Test("permanent purchases apply only to the next run", () => { var g = New(); g.Start(); g.Meta.Points = 100; g.Purchase("attack"); Assert(g.Stats.Attack == 1 && g.Meta.Tech["attack"] == 1); g.ReturnToHub(); Assert(MathF.Abs(g.Stats.Attack - 1.12f) < .001f); });
        Test("two unlocked passive slots are enforced", () => { var g = New(); foreach (string k in g.Meta.Passives.Keys.ToArray()) g.Meta.Passives[k] = 1; g.Equip("siphon"); g.Equip("rage"); g.Equip("salvage"); Assert(g.Meta.Equipped.Count == 2); g.Equip("rage"); g.Equip("salvage"); Assert(g.Meta.Equipped.Contains("salvage")); });
        Test("death retains research and blueprints; redeployment is free", () => { var g = New(); g.Start(); g.Collect(new() { Kind = "point", Value = 22 }); g.Collect(new() { Kind = "blueprint", Blueprint = "cannon" }); g.Hit(g.Blocks[0], 99999); Assert(g.Panel == "result"); g.ReturnToHub(); g.Start(); Assert(g.Meta.Points == 22 && g.Meta.Blueprints.Contains("cannon") && g.Scrap == 0 && g.Inventory.Count == 0 && g.Blocks[0].Hp == 160); });
        Test("atomic JSON save restores on a new client session", () => { var g = New(); g.Meta.Points = 55; g.Meta.Settings.Shake = false; g.Save(); var reload = new GameModel(g.Store); Assert(reload.Meta.Points == 55 && !reload.Meta.Settings.Shake); Assert(File.Exists(g.Store.PathName)); });
        Test("corrupt saves recover a valid backup", () => { var g = New(); g.Meta.Points = 10; g.Save(); g.Meta.Points = 20; g.Save(); File.WriteAllText(g.Store.PathName, "{broken"); var reload = new GameModel(g.Store); Assert(reload.Meta.Points == 10); });
        Test("eight rooms form a complete expedition", () => { var g = New(); g.Start(); for (int i = 0; i < 8; i++) { Assert(g.Room == i); if (i is 3 or 6) { Assert(g.Clear && g.FreeRepair); g.Repair(); } else if (i == 7) { Assert(g.Enemies[0].Kind == "boss"); g.Enemies[0].Hp = 0; g.Kill(g.Enemies[0]); } else { for (int w = 0; w < 4; w++) { g.SpawnWave(); foreach (var e in g.Enemies.ToArray()) { e.Hp = 0; g.Kill(e); } g.Enemies.Clear(); } g.Update(1f / 60); Assert(g.Clear); foreach (var d in g.Drops) g.Collect(d); g.Drops.Clear(); } if (i < 7) g.Next(i % 2 == 0 ? "arms" : "research"); } Assert(g.Victory && g.Meta.Wins == 1 && g.Meta.Points >= 40); });
        Test("paused simulation advances neither player nor enemies", () => { var g = New(); g.Start(); g.Movement = Vector2.Right; g.Open("pause"); Vector2 pos = g.Position; float t = g.Elapsed; g.Update(1); Assert(g.Position == pos && g.Elapsed == t); });
        GD.Print($"SELF TESTS: {passed} passed / {failures} failed"); return failures;
    }
}
